SEED='demo'
W="await T.w(450);"
def mk(name,ty='check',extra=''):
    return "openEdit(null);"+W+"T.set('#fName',"+repr(name)+");"+("T.click('#typeRow [data-ty=\""+ty+"\"]');await T.w(150);" if ty!='check' else '')+extra+"T.click('#saveBtn');"+W
CASES=[
 ('HAB-01','Habits','Create a Yes/No habit',"(async()=>{"+mk('QA Check')+"const h=state.habits.find(h=>h.name==='QA Check');return T.ok(h&&h.type!=='count','type '+(h&&h.type))})()"),
 ('HAB-02','Habits','Create a Count habit with target 3',"(async()=>{"+mk('QA Count','count',"T.set('#fTarget','3');")+"const h=state.habits.find(h=>h.name==='QA Count');return T.ok(h&&h.type==='count'&&+h.target===3,h&&(h.type+' target '+h.target))})()"),
 ('HAB-03','Habits','Create Time, Avoid and Money habits',"(async()=>{"+mk('QA Time','time')+mk('QA Neg','neg')+mk('QA Money','money')+"const t=['QA Time','QA Neg','QA Money'].map(n=>(state.habits.find(h=>h.name===n)||{}).type);return T.ok(t.join()==='time,neg,money',t)})()"),
 ('HAB-04','Habits','Empty name is rejected',"(async()=>{const n=state.habits.length;openEdit(null);"+W+"T.set('#fName','   ');T.click('#saveBtn');"+W+"const ok=state.habits.length===n&&sheetOpen==='addSheet';closeSheet();return T.ok(ok,'count '+n+'->'+state.habits.length)})()"),
 ('HAB-05','Habits','Tap to complete, tap again to undo',"(async()=>{showTab('pgHabits');"+W+"const h=state.habits.find(h=>h.name==='QA Check');const c=()=>T.q('#list .card[data-id=\"'+h.id+'\"] [data-act=chk]');c().click();"+W+"const a=isDone(h,today());c().click();"+W+"const b=isDone(h,today());return T.ok(a&&!b,'done '+a+' then '+b)})()"),
 ('HAB-06','Habits','Count habit completes only when the target is reached',"(async()=>{showTab('pgHabits');"+W+"const h=state.habits.find(h=>h.name==='QA Count');const c=()=>T.q('#list .card[data-id=\"'+h.id+'\"] [data-act=chk]');const r=[];for(let i=0;i<3;i++){c().click();await T.w(250);r.push(isDone(h,today()));}return T.ok(!r[0]&&r[2],r)})()"),
 ('HAB-07','Habits','Streak counts consecutive days',"(()=>{const s=streak(state.habits[0]);return T.ok(typeof s==='number'&&s>=0,'demo habit streak '+s)})()"),
 ('HAB-08','Habits','Habit detail opens and shows its stats',"(async()=>{const h=state.habits[0];openDetail(h.id);"+W+"return T.ok(sheetOpen==='detailSheet'&&T.q('#sStreak').textContent!=='','detail sheet open, streak '+T.q('#sStreak').textContent)})()"),
 ('HAB-09','Habits','Edit a habit name',"(async()=>{const h=state.habits.find(h=>h.name==='QA Check');openDetail(h.id);await T.w(700);T.click('#btnEdit');await T.w(800);T.set('#fName','QA Check 2');T.click('#saveBtn');"+W+"const n=state.habits.find(x=>x.id===h.id).name;return T.ok(n==='QA Check 2',n)})()"),
 ('HAB-10','Habits','Archive hides the habit; it can be restored',"(async()=>{const h=state.habits.find(h=>h.name==='QA Neg');openDetail(h.id);"+W+"const b=T.q('#archBtn');if(!b)return T.ok(false,'no archive button');b.click();"+W+"const arch=!!h.arch;showTab('pgHabits');await T.w(300);const shown=!!T.q('#list .card[data-id=\"'+h.id+'\"]');h.arch=false;h.archAt='';persist();return T.ok(arch&&!shown,'archived '+arch+' shown '+shown)})()"),
 ('HAB-11','Habits','Delete moves the habit to Recently deleted; restore brings it back',"(async()=>{const h=state.habits.find(h=>h.name==='QA Time');openDetail(h.id);"+W+"window.confirm=()=>true;const d=T.q('#delBtn');d.click();"+W+"if(state.habits.some(x=>x.id===h.id)){d.click();"+W+"}const gone=!state.habits.some(x=>x.id===h.id);const ix=(state.trash||[]).findIndex(t=>t.item&&t.item.id===h.id);if(ix>=0)restoreFromTrash(ix);return T.ok(gone&&ix>=0&&state.habits.some(x=>x.id===h.id),'deleted '+gone+' in trash '+(ix>=0))})()"),
 ('HAB-12','Habits','Code in a habit name is shown as text, never run',"(async()=>{window.__xss=0;"+mk('<img src=x onerror=\"window.__xss=1\">XSS')+"showTab('pgHabits');await T.w(600);gSearchRun('XSS');await T.w(200);return T.ok(window.__xss===0&&!T.q('#list img[src=\"x\"]'),'executed: '+window.__xss)})()"),
 ('HAB-13','Habits','Very long name (200 characters) does not break the card',"(async()=>{"+mk('LONG')+"const h=state.habits.find(h=>h.name==='LONG');h.name='L'.repeat(200);persist();showTab('pgHabits');await T.w(400);const r=T.q('#list .card[data-id=\"'+h.id+'\"]').getBoundingClientRect();return T.ok(r.right<=innerWidth+1&&document.documentElement.scrollWidth<=innerWidth+1,'card right '+Math.round(r.right)+' / '+innerWidth)})()"),
 ('HAB-14','Habits','Emoji-only name saves and displays',"(async()=>{"+mk('🔥💧📚')+"return T.ok(state.habits.some(h=>h.name==='🔥💧📚'),'saved')})()"),
 ('HAB-15','Habits','Reminder time is saved with the habit',"(async()=>{openEdit(null);"+W+"T.set('#fName','QA Remind');const m=T.q('#habitMoreBtn');if(m)m.click();await T.w(200);const a=T.q('#btnAddTime');if(a){a.click();await T.w(200);}const t=T.q('#remList input[type=time]');if(t){t.value='07:30';t.dispatchEvent(new Event('change',{bubbles:true}));}T.click('#saveBtn');"+W+"const h=state.habits.find(h=>h.name==='QA Remind');return T.ok(h&&JSON.stringify(h).includes('07:30'),'reminder 07:30 saved: '+!!(h&&JSON.stringify(h).includes('07:30')))})()"),
 ('HAB-16','Habits','Double-tap Save creates the habit only once',"(async()=>{openEdit(null);"+W+"T.set('#fName','QA Double');const b=T.q('#saveBtn');b.click();b.click();"+W+"return T.ok(state.habits.filter(h=>h.name==='QA Double').length===1,state.habits.filter(h=>h.name==='QA Double').length+' created')})()"),
 ('HAB-17','Habits','Suggested habits do not include Journal',"(async()=>{openEdit(null);"+W+"const t=T.q('#tplRow')?T.q('#tplRow').innerText:'';closeSheet();return T.ok(!/\\bJournal\\b/.test(t),t.slice(0,80))})()"),
 ('HAB-18','Habits','Habits survive a reload',"RELOAD:(()=>T.ok(['QA Check 2','QA Count','QA Money','🔥💧📚'].every(n=>state.habits.some(h=>h.name===n)),state.habits.length+' habits'))()"),
]
